BAD=set()
def variant(k,sc): return C[k]
SHORT={'BABY':'you as a baby','YOU4':'you (age 4)','YOU6':'you (age 6)','YOU7':'you (age 7)','YOU16':'you (age 16)','YOU':'you','YOUPART':'you (partisan)','LEON7':'Leon (age 7)','LEON16':'Leon','LEONPART':'Leon (partisan)','FATHER':'your father','FATHERAGED':'your father','MOTHER':'your mother','LEONFATHER':"Leon's father",'PORPHYRIUS':'Porphyrius','JUSTINIAN':'Justinian','THEODORA':'Theodora','JOHN':'John the Cappadocian','HYPATIUS':'Hypatius','NARSES':'Narses','BELISARIUS':'Belisarius','PROCOPIUS':'Procopius','MONKS':'monks'}
CAM={'W':'Wide establishing shot, eye level','M':'Medium shot, eye level','C':'Close-up, eye level','ECU':'Extreme close-up','HA':'High-angle shot looking down','TD':'Top-down overhead shot','LA':'Low-angle shot looking up','POV':'First-person point-of-view shot','OTS':'Over-the-shoulder shot'}
fix={93:"dazed spiral eyes"}
rows=[]
for line in open('shots.txt'):
    if not line.strip(): continue
    n,sc,cam,mood,act,vo=line.rstrip('\n').split('|',5)
    n=int(n)
    act=act.replace('with X-eyes for a moment','with dazed spiral eyes')
    import re
    a=re.sub(r'^(extreme close-up of|close-up of|high-angle view of|top-down view of|low-angle view of|wide view of|extreme detail on|a cutaway of)\s+','',act)
    for k in sorted(C,key=len,reverse=True): a=a.replace('{'+k+'}',variant(k,'indoor' if n in BAD else sc))
    short=act
    for k in C: short=short.replace('{'+k+'}',SHORT.get(k,k.lower()))
    env,light=S[sc]
    prompt=f"{CAM[cam]} of {a}. Setting: {env}. Lighting: {light}. Mood: {mood}. Style: {STYLE}."
    rows.append(dict(n=n,seg=beats[n-1],prompt=prompt,cam=CAM[cam],light=light,mood=mood,action=short[0].upper()+short[1:],vo=vo.strip()))
assert [r['n'] for r in rows]==list(range(1,len(beats)+1)), "mismatch"
json.dump(rows,open('prompts.json','w'),indent=1)
with open('image_prompts.md','w') as f:
    f.write("# Why It Sucks to Be a Sports Fan (in Byzantine Constantinople) — Image + Voiceover Prompts\n\n298 beats · ~3–5 s each · Visual Style Profile locked · Characters locked to the Yesteryears character sheets\n\n"
  "**Voiceover:** every beat has a direction in [emotion] tag form plus pace, emphasis and pause notes. The tags work directly in ElevenLabs v3 and similar tools; for other voices, read them as acting notes. Keep the base voice calm, deadpan and close-mic, and let the tags shift it.\n\n"
  "**Headwear rule:** headwear fits the character's class and the scene. Everyone in this episode is bareheaded except the Emperor and Empress, whose diadems are royal regalia.\n\n"
  "**Character lock**\n\n| Story role | Sheet |\n|---|---|\n| You, age 4 / 6 / 7 | Boy variant, bareheaded |\n| You, 16 / 18 / partisan | Mascot (partisan haircut, beard and green puffed sleeves from 18) |\n| Your mother | Adult woman variant |\n"
  "| Father, Leon, Leon's father, Porphyrius, Justinian, Theodora, John, Hypatius, Narses, Belisarius, Procopius, monks | Not on a sheet (fixed descriptions) |\n\n")
    for r in rows:
        f.write(f"## Beat {r['n']}\n**[Script Segment]** \"{r['seg']}\"\n\n**Image Prompt:** {r['prompt']}\n\n- **Camera Angle:** {r['cam']}\n- **Lighting:** {r['light']}\n- **Mood:** {r['mood']}\n- **Action:** {r['action']}\n- **Voiceover direction:** {r['vo']}\n\n")
print(len(rows))
